WITH sales_agg AS (SELECT cs_warehouse_sk, cs_sold_date_sk, SUM(cs_quantity) AS total_sales_qty FROM catalog_sales GROUP BY cs_warehouse_sk, cs_sold_date_sk), returns_agg AS (SELECT cr_warehouse_sk, cr_returned_date_sk, SUM(cr_return_quantity) AS total_return_qty FROM catalog_returns GROUP BY cr_warehouse_sk, cr_returned_date_sk), combined AS (SELECT s.cs_warehouse_sk AS warehouse_sk, s.cs_sold_date_sk AS date_sk, s.total_sales_qty, COALESCE(r.total_return_qty, 0) AS total_return_qty, CASE WHEN s.total_sales_qty = 0 THEN 0 ELSE (COALESCE(r.total_return_qty, 0) * 100.0) / s.total_sales_qty END AS return_rate_pct FROM sales_agg s LEFT JOIN returns_agg r ON s.cs_warehouse_sk = r.cr_warehouse_sk AND s.cs_sold_date_sk = r.cr_returned_date_sk) SELECT w.w_warehouse_id, w.w_warehouse_name, w.w_city, w.w_state, c.date_sk, c.total_sales_qty, c.total_return_qty, c.return_rate_pct, CASE WHEN w.w_warehouse_sq_ft < 100000 THEN 'Small' WHEN w.w_warehouse_sq_ft < 500000 THEN 'Medium' ELSE 'Large' END AS size_category, DENSE_RANK() OVER (PARTITION BY CASE WHEN w.w_warehouse_sq_ft < 100000 THEN 'Small' WHEN w.w_warehouse_sq_ft < 500000 THEN 'Medium' ELSE 'Large' END ORDER BY c.return_rate_pct DESC) AS size_category_return_rank, AVG(c.return_rate_pct) OVER (PARTITION BY w.w_warehouse_id ORDER BY c.date_sk ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS moving_avg_return_rate_3d FROM combined c JOIN warehouse w ON c.warehouse_sk = w.w_warehouse_sk ORDER BY w.w_warehouse_id, c.date_sk
